{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The share of each shape's pictures the network names right.",
  "transform": [
    {
      "calculate": "datum.predicted === datum.shape ? 100 : 0",
      "as": "right"
    },
    {
      "aggregate": [
        {
          "op": "mean",
          "field": "right",
          "as": "accuracy"
        }
      ],
      "groupby": [
        "shape"
      ]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "shape",
      "type": "nominal",
      "title": null,
      "axis": {
        "labelAngle": 0
      }
    },
    "y": {
      "field": "accuracy",
      "type": "quantitative",
      "title": "Named right (%)",
      "scale": {
        "domain": [
          0,
          100
        ]
      }
    },
    "color": {
      "field": "shape",
      "type": "nominal",
      "legend": null
    },
    "tooltip": [
      {
        "field": "shape"
      },
      {
        "field": "accuracy",
        "format": ".0f"
      }
    ]
  }
}
